-- table: _migrations
CREATE TABLE _migrations (
        id         TEXT PRIMARY KEY,
        applied_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

-- table: agent_model_configs
CREATE TABLE agent_model_configs (
  id                    TEXT PRIMARY KEY,
  name                  TEXT NOT NULL,
  thinking_provider_id  TEXT NOT NULL,
  executor_provider_id  TEXT NOT NULL,
  embedding_provider_id TEXT NOT NULL,
  active                INTEGER NOT NULL DEFAULT 0 CHECK (active IN (0, 1)),
  created_at            TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: agent_personas
CREATE TABLE agent_personas (
  id                TEXT PRIMARY KEY,
  name              TEXT NOT NULL,
  role              TEXT NOT NULL,
  description       TEXT NOT NULL DEFAULT '',
  system_prompt     TEXT NOT NULL DEFAULT '',
  default_skill_ids TEXT NOT NULL DEFAULT '[]',
  provider_id       TEXT NOT NULL DEFAULT 'provider-deepseek',
  enabled           INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
, thinking_provider_id TEXT, memory TEXT DEFAULT '');

-- table: agent_skills
CREATE TABLE agent_skills (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  tool_ids    TEXT NOT NULL DEFAULT '[]',
  prompt      TEXT NOT NULL DEFAULT '',
  enabled     INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: ai_tools
CREATE TABLE ai_tools (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  description    TEXT NOT NULL DEFAULT '',
  kind           TEXT NOT NULL CHECK (kind IN ('mcp','cli','http','browser')),
  status         TEXT NOT NULL DEFAULT 'needs_config' CHECK (status IN ('enabled','needs_config','disabled')),
  risk           TEXT NOT NULL DEFAULT 'read_only' CHECK (risk IN ('read_only','write','admin')),
  input_schema   TEXT NOT NULL DEFAULT '{}',
  example_prompt TEXT NOT NULL DEFAULT '',
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: analysis_results
CREATE TABLE analysis_results (
  id                  TEXT PRIMARY KEY,
  summary             TEXT NOT NULL,
  screenshot_types    TEXT NOT NULL DEFAULT '[]',
  business_objects    TEXT NOT NULL DEFAULT '[]',
  fields              TEXT NOT NULL DEFAULT '[]',
  workflow_stages     TEXT NOT NULL DEFAULT '[]',
  problems            TEXT NOT NULL DEFAULT '[]',
  automation_rules    TEXT NOT NULL DEFAULT '[]',
  dashboard_metrics   TEXT NOT NULL DEFAULT '[]',
  implementation_plan TEXT NOT NULL DEFAULT '[]',
  created_at          TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: approvals
CREATE TABLE approvals (
  id              TEXT PRIMARY KEY,
  enterprise_id   TEXT NOT NULL,
  requestor_id    TEXT,
  approver_id     TEXT,
  object_type     TEXT NOT NULL,
  object_id       TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','approved','rejected','cancelled')),
  comment         TEXT NOT NULL DEFAULT '',
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  resolved_at     TEXT
);

-- table: audit_logs
CREATE TABLE audit_logs (
  id              TEXT PRIMARY KEY,
  enterprise_id   TEXT NOT NULL,
  user_id         TEXT,
  action          TEXT NOT NULL,
  object_type     TEXT NOT NULL,
  object_id       TEXT,
  changes         TEXT NOT NULL DEFAULT '{}',
  ip_address      TEXT NOT NULL DEFAULT '',
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: automation_jobs
CREATE TABLE automation_jobs (
  id               TEXT PRIMARY KEY,
  automation_id    TEXT NOT NULL,
  trigger_source   TEXT NOT NULL,
  trigger_event    TEXT NOT NULL DEFAULT '{}',
  dedupe_key       TEXT NOT NULL UNIQUE,
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending','running','success','failed','dead')),
  attempts         INTEGER NOT NULL DEFAULT 0,
  max_attempts     INTEGER NOT NULL DEFAULT 3,
  available_at     TEXT NOT NULL,
  lease_owner      TEXT,
  lease_expires_at TEXT,
  output           TEXT NOT NULL DEFAULT '',
  error_message    TEXT NOT NULL DEFAULT '',
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  started_at       TEXT,
  completed_at     TEXT
);

-- table: automation_leases
CREATE TABLE automation_leases (
  automation_id    TEXT PRIMARY KEY,
  owner_id         TEXT NOT NULL,
  acquired_at      TEXT NOT NULL,
  heartbeat_at     TEXT NOT NULL,
  lease_expires_at TEXT NOT NULL
);

-- table: automation_runs
CREATE TABLE automation_runs (
  id            TEXT PRIMARY KEY,
  automation_id TEXT NOT NULL,
  status        TEXT NOT NULL CHECK (status IN ('success','error')),
  trigger_event TEXT NOT NULL DEFAULT '{}',
  output        TEXT NOT NULL DEFAULT '',
  error_message TEXT NOT NULL DEFAULT '',
  duration_ms   INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: automations
CREATE TABLE automations (
  id               TEXT PRIMARY KEY,
  project_id       TEXT NOT NULL,
  name             TEXT NOT NULL,
  trigger_desc     TEXT NOT NULL,
  trigger_type     TEXT NOT NULL CHECK (trigger_type IN ('schedule','message','webhook','email','file','manual')),
  action_desc      TEXT NOT NULL,
  action_type      TEXT NOT NULL CHECK (action_type IN ('send_email','call_ai','shell','api_call','notify','browser','tool_call')),
  agent_model      TEXT,
  action_plugin_id TEXT,
  action_tool_id   TEXT,
  action_input     TEXT NOT NULL DEFAULT '{}',
  workflow_graph   TEXT,
  system_prompt    TEXT,
  webhook_secret   TEXT,
  enabled          INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  run_count        INTEGER NOT NULL DEFAULT 0,
  last_run         TEXT,
  last_status      TEXT CHECK (last_status IN ('success','error')),
  last_output      TEXT,
  last_error       TEXT,
  last_duration_ms INTEGER
);

-- table: business_event_deliveries
CREATE TABLE business_event_deliveries (
  event_id         TEXT NOT NULL,
  handler_key      TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending','running','success','failed','dead')),
  attempts         INTEGER NOT NULL DEFAULT 0,
  max_attempts     INTEGER NOT NULL DEFAULT 5,
  available_at     TEXT NOT NULL,
  lease_owner      TEXT,
  lease_expires_at TEXT,
  last_error       TEXT NOT NULL DEFAULT '',
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  completed_at     TEXT,
  PRIMARY KEY (event_id, handler_key)
);

-- table: business_events
CREATE TABLE business_events (
  id            TEXT PRIMARY KEY,
  event_type    TEXT NOT NULL,
  object_type   TEXT,
  object_id     TEXT,
  payload       TEXT NOT NULL DEFAULT '{}',
  source        TEXT NOT NULL DEFAULT 'system',
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  processed     INTEGER NOT NULL DEFAULT 0 CHECK (processed IN (0, 1))
, dispatch_status TEXT NOT NULL DEFAULT 'pending'
  CHECK (dispatch_status IN ('pending','processing','success','failed','dead')), attempt_count INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 5, available_at TEXT, lease_owner TEXT, lease_expires_at TEXT, last_error TEXT NOT NULL DEFAULT '', processed_at TEXT);

-- table: business_object_statuses
CREATE TABLE business_object_statuses (
  id              TEXT PRIMARY KEY,
  object_type     TEXT NOT NULL,
  object_id       TEXT NOT NULL,
  status          TEXT NOT NULL,
  previous_status TEXT,
  changed_by      TEXT,
  changed_at      TEXT NOT NULL DEFAULT (datetime('now')),
  comment         TEXT NOT NULL DEFAULT ''
);

-- table: conversations
CREATE TABLE conversations (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  project_id    TEXT NOT NULL,
  title         TEXT NOT NULL,
  tags          TEXT NOT NULL DEFAULT '[]',
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
, scope_enterprise_ids TEXT NOT NULL DEFAULT '[]', scope_project_ids TEXT NOT NULL DEFAULT '[]', persona_id TEXT);

-- table: customers
CREATE TABLE customers (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  name          TEXT NOT NULL,
  contact       TEXT NOT NULL DEFAULT '',
  phone         TEXT NOT NULL DEFAULT '',
  email         TEXT NOT NULL DEFAULT '',
  address       TEXT NOT NULL DEFAULT '',
  tags          TEXT NOT NULL DEFAULT '[]',
  status        TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active','inactive','lead','lost')),
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
, gender TEXT NOT NULL DEFAULT 'unknown'
  CHECK (gender IN ('unknown','male','female','other')), project_id TEXT);

-- table: departments
CREATE TABLE departments (
        id            TEXT PRIMARY KEY,
        enterprise_id TEXT NOT NULL,
        parent_id     TEXT,
        name          TEXT NOT NULL,
        created_at    TEXT NOT NULL DEFAULT (datetime('now'))
      );

-- table: enterprises
CREATE TABLE enterprises (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL
, tags TEXT NOT NULL DEFAULT '[]');

-- table: files
CREATE TABLE files (
  id              TEXT PRIMARY KEY,
  enterprise_id   TEXT NOT NULL,
  filename        TEXT NOT NULL,
  mime_type       TEXT NOT NULL,
  size            INTEGER NOT NULL DEFAULT 0,
  storage_path    TEXT NOT NULL,
  uploaded_by     TEXT,
  related_type    TEXT,
  related_id      TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
, project_id TEXT);

-- table: integration_runs
CREATE TABLE integration_runs (
  id                TEXT PRIMARY KEY,
  integration_type  TEXT NOT NULL,
  object_type       TEXT,
  object_id         TEXT,
  status            TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','running','success','failed','cancelled')),
  request_payload   TEXT NOT NULL DEFAULT '{}',
  response_payload  TEXT NOT NULL DEFAULT '',
  error_message     TEXT NOT NULL DEFAULT '',
  retry_count       INTEGER NOT NULL DEFAULT 0,
  max_retries       INTEGER NOT NULL DEFAULT 3,
  next_retry_at     TEXT,
  idempotency_key   TEXT UNIQUE,
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at      TEXT
, lease_owner TEXT, lease_expires_at TEXT, heartbeat_at TEXT);

-- table: invoices
CREATE TABLE invoices (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  order_id      TEXT,
  customer_id   TEXT,
  amount        REAL NOT NULL,
  status        TEXT NOT NULL DEFAULT 'draft'
                CHECK (status IN ('draft','issued','paid','overdue','cancelled')),
  due_date      TEXT,
  issued_at     TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
, invoice_number TEXT, invoice_code TEXT, invoice_type TEXT, tax_rate REAL, tax_amount REAL, total_amount REAL, buyer_name TEXT, buyer_tax_id TEXT, seller_name TEXT, seller_tax_id TEXT, remark TEXT, issuer TEXT, source_file_id TEXT, project_id TEXT);

-- table: library_items
CREATE TABLE library_items (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  project_id    TEXT NOT NULL,
  name          TEXT NOT NULL,
  type          TEXT NOT NULL CHECK (type IN ('screenshot', 'spreadsheet', 'document', 'note')),
  summary       TEXT NOT NULL,
  visibility    TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'private')),
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: maintenance_runs
CREATE TABLE maintenance_runs (
  task_name        TEXT NOT NULL,
  schedule_slot    TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending','running','success','failed','dead')),
  attempts         INTEGER NOT NULL DEFAULT 0,
  max_attempts     INTEGER NOT NULL DEFAULT 3,
  available_at     TEXT NOT NULL,
  lease_owner      TEXT,
  lease_expires_at TEXT,
  error_message    TEXT NOT NULL DEFAULT '',
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  completed_at     TEXT,
  PRIMARY KEY (task_name, schedule_slot)
);

-- table: messages
CREATE TABLE messages (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL,
  role            TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content         TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: model_providers
CREATE TABLE model_providers (
  id              TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  base_url        TEXT NOT NULL,
  model           TEXT NOT NULL,
  api_key_env     TEXT NOT NULL,
  enabled         INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
, embedding_base_url TEXT NOT NULL DEFAULT '', embedding_model TEXT NOT NULL DEFAULT '', embedding_api_key TEXT NOT NULL DEFAULT '', provider_type TEXT NOT NULL DEFAULT 'chat'
  CHECK (provider_type IN ('chat', 'embedding')));

-- table: order_items
CREATE TABLE order_items (
  id          TEXT PRIMARY KEY,
  order_id    TEXT NOT NULL,
  product_id  TEXT,
  quantity    REAL NOT NULL DEFAULT 1,
  unit_price  REAL NOT NULL DEFAULT 0,
  subtotal    REAL NOT NULL DEFAULT 0
);

-- table: orders
CREATE TABLE orders (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  customer_id   TEXT,
  status        TEXT NOT NULL DEFAULT 'draft'
                CHECK (status IN ('draft','confirmed','processing','shipped','delivered','cancelled','refunded')),
  total_amount  REAL NOT NULL DEFAULT 0,
  notes         TEXT NOT NULL DEFAULT '',
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
, project_id TEXT);

-- table: payments
CREATE TABLE payments (
  id            TEXT PRIMARY KEY,
  enterprise_id TEXT NOT NULL,
  order_id      TEXT,
  amount        REAL NOT NULL,
  method        TEXT NOT NULL DEFAULT 'cash'
                CHECK (method IN ('cash','bank_transfer','alipay','wechat','credit_card','other')),
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','completed','failed','refunded')),
  received_at   TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
, project_id TEXT);

-- table: plugin_configs
CREATE TABLE plugin_configs (
