-- table: tasks
CREATE TABLE tasks (
  id              TEXT PRIMARY KEY,
  enterprise_id   TEXT NOT NULL,
  assignee_id     TEXT,
  title           TEXT NOT NULL,
  description     TEXT NOT NULL DEFAULT '',
